union U{a:u32,b:u32}const fn image(n:u32)->u32{let mut u=U{a:0};let p=&raw mut u.a;let mut i=0u32;while i<n{unsafe{let r=&mut *p;*r+=1;}i+=1;}unsafe{u.b}}const fn ordinary(n:u32)->u32{let mut x=0u32;let p=&mut x;let mut i=0u32;while i<n{{let r=&mut *p;*r+=1;}i+=1;}x}const A:u32=image(8);const B:u32=image(32);const C:u32=image(128);const D:u32=ordinary(8);const E:u32=ordinary(32);const F:u32=ordinary(128);fn main(){check(A==8);check(B==32);check(C==128);check(A==D);check(B==E);check(C==F);}
